export async function cutImageRegion(imageLayer, region) {
  // imageLayer: ol/layer/Image (ImageLayer) with ImageStatic source
  // region: either [minX,minY,maxX,maxY] in same CRS as imageExtent, or a GeoJSON Feature/Geometry
  function getExtentFromGeoJSON(g) {
    // supports Feature or Geometry or FeatureCollection
    if (!g) return null;
    if (Array.isArray(g) && g.length === 4 && typeof g[0] === 'number') return g;
    if (g.type === 'FeatureCollection') {
      let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
      (g.features || []).forEach((f) => {
        const e = getExtentFromGeoJSON(f);
        if (!e) return;
        minX = Math.min(minX, e[0]);
        minY = Math.min(minY, e[1]);
        maxX = Math.max(maxX, e[2]);
        maxY = Math.max(maxY, e[3]);
      });
      if (minX === Infinity) return null;
      return [minX, minY, maxX, maxY];
    }
    if (g.type === 'Feature') return getExtentFromGeoJSON(g.geometry);
    if (g.type === 'Polygon' || g.type === 'MultiPolygon') {
      let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
      const coords = g.coordinates;
      const iterate = (arr) => {
        arr.forEach((c) => {
          if (Array.isArray(c[0])) iterate(c);
          else {
            const x = Number(c[0]) || 0;
            const y = Number(c[1]) || 0;
            minX = Math.min(minX, x);
            minY = Math.min(minY, y);
            maxX = Math.max(maxX, x);
            maxY = Math.max(maxY, y);
          }
        });
      };
      iterate(coords);
      if (minX === Infinity) return null;
      return [minX, minY, maxX, maxY];
    }
    if (g.type === 'Point') {
      const x = Number(g.coordinates[0]) || 0;
      const y = Number(g.coordinates[1]) || 0;
      return [x, y, x, y];
    }
    return null;
  }

  const src = imageLayer && imageLayer.getSource && imageLayer.getSource();
  if (!src) throw new Error('Invalid image layer source');
  // For ImageStatic source
  const imageExtent = (typeof src.getImageExtent === 'function') ? src.getImageExtent() : (src.imageExtent || null);
  const url = src.getUrl ? src.getUrl() : src.getUrls ? (src.getUrls()[0]) : (src.url || null);
  if (!url || !imageExtent) throw new Error('ImageLayer must have accessible URL and imageExtent');

  // load image
  const img = await new Promise((resolve, reject) => {
    const i = new Image();
    i.crossOrigin = 'anonymous';
    i.onload = () => resolve(i);
    i.onerror = (e) => reject(new Error('Failed to load image at ' + url));
    i.src = url;
  });

  const imgW = img.width;
  const imgH = img.height;
  const bbox = getExtentFromGeoJSON(region);
  if (!bbox) throw new Error('Could not determine extent from region');

  // clamp bbox to imageExtent intersection
  const ix0 = imageExtent[0], iy0 = imageExtent[1], ix1 = imageExtent[2], iy1 = imageExtent[3];
  const bx0 = Math.max(bbox[0], ix0);
  const by0 = Math.max(bbox[1], iy0);
  const bx1 = Math.min(bbox[2], ix1);
  const by1 = Math.min(bbox[3], iy1);
  if (bx1 <= bx0 || by1 <= by0) return null; // no intersection

  // compute pixel coordinates (sx, sy, sw, sh) from extent
  const sx = Math.round(((bx0 - ix0) / (ix1 - ix0)) * imgW);
  const sy = Math.round(((iy1 - by1) / (iy1 - iy0)) * imgH); // canvas y origin is top
  const sw = Math.max(1, Math.round(((bx1 - bx0) / (ix1 - ix0)) * imgW));
  const sh = Math.max(1, Math.round(((by1 - by0) / (iy1 - iy0)) * imgH));

  // clamp
  const csx = Math.max(0, Math.min(imgW - 1, sx));
  const csy = Math.max(0, Math.min(imgH - 1, sy));
  const csw = Math.max(1, Math.min(imgW - csx, sw));
  const csh = Math.max(1, Math.min(imgH - csy, sh));

  const canvas = document.createElement('canvas');
  canvas.width = csw;
  canvas.height = csh;
  const ctx = canvas.getContext('2d');
  ctx.drawImage(img, csx, csy, csw, csh, 0, 0, csw, csh);
  const imageData = ctx.getImageData(0, 0, csw, csh);
  const dataUrl = canvas.toDataURL('image/png');

  return {
    dataUrl,
    imageData,
    extent: [bx0, by0, bx1, by1],
    width: csw,
    height: csh,
  };
}

export default cutImageRegion;

// Run geowarp and create an OpenLayers ImageLayer from the warped single-band result,
// then optionally cut the resulting image for the requested region.
// Parameters:
// - gwOpts: options object passed to geowarp
// - res: the result object from readTiffAutoLevel (used for fallbacks)
// - opts: {
//     classColorMap, paletteArray, normalizeToHex, parseColorToRgba,
//     responseColorFilterHex, cutlineRegion
//   }
export async function geowarpAndCreateResponse(gwOpts, res, opts = {}) {
  const {
    classColorMap = {},
    paletteArray = [],
    normalizeToHex = (c) => (Array.isArray(c) ? (`#${[c[0], c[1], c[2]].map(v => Number(v).toString(16).padStart(2,'0')).join('')}`.toLowerCase()) : null),
    parseColorToRgba = (c) => (Array.isArray(c) ? c : [0,0,0,0]),
    responseColorFilterHex = null,
    cutlineRegion = null,
  } = opts;

  // lazy import geowarp and OL classes here to avoid circular/top-level import assumptions
  // Note: project already depends on geowarp and ol; these imports should be tree-shaken
  // when bundling.
  // eslint-disable-next-line no-undef
  const geowarp = await (async () => { try { return (await import('geowarp')).default || (await import('geowarp')); } catch (e) { return null; } })();
  if (!geowarp) throw new Error('geowarp module not available');

  const ImageStatic = (await import('ol/source/ImageStatic.js')).default;
  const ImageLayer = (await import('ol/layer/Image.js')).default;

  let warped;
  try {
    warped = await geowarp(gwOpts);
  } catch (err) {
    throw err;
  }

  // If there's no band data, return the warped object for caller to decide
  if (!warped || !warped.data || !warped.data[0]) {
    return { warped };
  }

  const outW = warped.out_width || (res && res.width) || 0;
  const outH = warped.out_height || (res && res.height) || 0;
  const band = warped.data[0];

  const tmpCanvas = document.createElement('canvas');
  tmpCanvas.width = outW;
  tmpCanvas.height = outH;
  const ctx = tmpCanvas.getContext('2d');
  const img = ctx.createImageData(outW, outH);

  for (let i = 0, p = 0; i < band.length && p < img.data.length; i++, p += 4) {
    const raw = band[i];
    const vnum = raw === null || raw === undefined ? NaN : Number(raw);
    const isNoData = Number.isNaN(vnum) || (typeof gwOpts !== 'undefined' && raw === gwOpts.out_no_data);
    if (isNoData) {
      img.data[p] = 0; img.data[p+1] = 0; img.data[p+2] = 0; img.data[p+3] = 0; continue;
    }
    const v = Math.round(vnum);
    let colorVal = classColorMap[v] || null;
    if (!colorVal) {
      const pal = paletteArray && paletteArray.length > v ? paletteArray[v] : null;
      colorVal = pal || null;
    }
    if (colorVal) {
      const colorHex = normalizeToHex(colorVal);
      if (responseColorFilterHex && colorHex !== responseColorFilterHex) {
        img.data[p] = 0; img.data[p+1] = 0; img.data[p+2] = 0; img.data[p+3] = 0;
      } else {
        const rgba = parseColorToRgba(colorVal);
        img.data[p] = rgba[0]; img.data[p+1] = rgba[1]; img.data[p+2] = rgba[2]; img.data[p+3] = rgba[3] || 255;
      }
    } else {
      img.data[p] = 0; img.data[p+1] = 0; img.data[p+2] = 0; img.data[p+3] = 0;
    }
  }

  ctx.putImageData(img, 0, 0);
  const dataUrl = tmpCanvas.toDataURL('image/png');
  const imageExtent = warped.out_bbox || (res && res.actualRasterBBox) || null;

  const imgSrc = new ImageStatic({ url: dataUrl, imageExtent: imageExtent, projection: 'EPSG:3857' });
  const imgLayer = new ImageLayer({ source: imgSrc });

  let cut = null;
  try {
    cut = await cutImageRegion(imgLayer, cutlineRegion || gwOpts.out_bbox);
  } catch (e) {
    // swallow cut errors but warn
    try { console.warn('cutImageRegion failed in geowarpAndCreateResponse:', e); } catch (ee) {}
  }

  return { warped, imgLayer, dataUrl, imageExtent, cut };
}

// Process drawn/selected shapes using the same pipeline as the original index2.js
// This function accepts a `ctx` object with required dependencies and UI refs.
export async function processShapes(shapes, ctx = {}) {
  const shouldExpandOnFinish = !!(shapes && shapes.length > 0);
  if (!shouldExpandOnFinish) return null;
  const {
    GeoJSON,
    readTiffAutoLevel,
    SpatialAnalysis,
    geowarpAndCreateResponse,
    classColorMap,
    paletteArray,
    normalizeToHex,
    parseColorToRgba,
    _responseColorFilterHex,
    setResponseColorFilter,
    renderChart,
    Chart,
    drawAreaEl,
    barCanvas,
    polarCanvas,
    statCanvas,
    barBox,
    polarBox,
    collapseDashboard,
    expandDashboard,
    map,
    responseGroup,
    toLonLat,
  } = ctx;

  try {
    try { setResponseColorFilter && setResponseColorFilter(null); } catch (e) {}
    const start = performance.now();
    const fmt = new GeoJSON();
    const geojson = shapes
      .map((f) => {
        if (!f) return null;
        if (f.type === "Feature" && f.geometry) return f;
        try {
          return JSON.parse(
            fmt.writeFeature(f, { featureProjection: "EPSG:3857", dataProjection: "EPSG:4326" }),
          );
        } catch (e) {
          try {
            return fmt.writeFeatureObject(f, { featureProjection: "EPSG:3857", dataProjection: "EPSG:4326" });
          } catch (err) {
            return null;
          }
        }
      })
      .filter(Boolean);

    const featureCollection = { type: "FeatureCollection", features: geojson.map((g) => (g.type === "Feature" ? g : { type: "Feature", geometry: g })), };

    const drawnFeatures = shapes
      .map((f) => {
        if (!f) return null;
        if (f.type === "Feature" && f.geometry) return f;
        try {
          return fmt.writeFeatureObject(f, { featureProjection: "EPSG:3857", dataProjection: "EPSG:4326" });
        } catch (e) {
          return null;
        }
      })
      .filter(Boolean);

    const merged = SpatialAnalysis.unionPolygons(drawnFeatures);
    const extent = SpatialAnalysis.getGeoJSONExtent(merged);
    let outputGeomMerc = SpatialAnalysis.convertToMercator(featureCollection);
    if (outputGeomMerc && outputGeomMerc.type === "Feature") outputGeomMerc = { type: "FeatureCollection", features: [outputGeomMerc] };

    const res = await readTiffAutoLevel("data/egypt_cog_final.tif?v=" + Date.now(), extent, 2000);
    const inputBand = ArrayBuffer.isView(res.data) ? Array.from(res.data) : Array.isArray(res.data) ? res.data : [res.data];
    const gwOpts = {
      in_data: [inputBand], in_width: res.width, in_height: res.height, in_bbox: res.actualRasterBBox, in_srs: 3857,
      out_bbox: res.actualRasterBBox, out_srs: 3857, out_width: res.width, out_height: res.height,
      cutline: outputGeomMerc, cutline_srs: 3857, outputFormat: "array", method: "nearest", turbo: true, out_no_data: 0,
    };

    let createResult;
    try {
      createResult = await geowarpAndCreateResponse(gwOpts, res, {
        classColorMap, paletteArray, normalizeToHex, parseColorToRgba, responseColorFilterHex: _responseColorFilterHex, cutlineRegion: outputGeomMerc || gwOpts.out_bbox,
      });
    } catch (err) {
      console.error('geowarp failed in processShapes:', err);
      return null;
    }

    const warped = createResult.warped;
    const outBbox = (warped && warped.out_bbox) || res.actualRasterBBox;
    const outW = (warped && warped.out_width) || res.width;
    const outH = (warped && warped.out_height) || res.height;

    let pixelAreaSqM = null;
    if (outBbox && outW && outH) {
      const bboxWidth = Math.abs(outBbox[2] - outBbox[0]);
      const bboxHeight = Math.abs(outBbox[3] - outBbox[1]);
      pixelAreaSqM = (bboxWidth * bboxHeight) / (outW * outH);
      const centerX = (outBbox[0] + outBbox[2]) / 2;
      const centerY = (outBbox[1] + outBbox[3]) / 2;
      const [, centerLat] = toLonLat([centerX, centerY]);
      const latRad = (centerLat * Math.PI) / 180;
      const distortionFactor = Math.cos(latRad) * Math.cos(latRad);
      pixelAreaSqM = pixelAreaSqM * distortionFactor;
    }

    const stats = SpatialAnalysis.calculateLandcoverHistogram((warped && warped.data && warped.data[0]) || [], 0, pixelAreaSqM);

    let totalPercent = 0; let totalAreaKm2 = 0;
    stats.forEach((s) => { const p = parseFloat(String(s.percentage).replace("%", "")) || 0; totalPercent += p; if (s.area_km2 != null) totalAreaKm2 += Number(s.area_km2); });
    totalPercent = Number(totalPercent.toFixed(2)); totalAreaKm2 = Number(totalAreaKm2.toFixed(4));

    try {
      const classLabels = { 10: "Tree cover", 20: "Shrubland", 30: "Grassland", 40: "Cropland", 50: "Built-up", 60: "Desert", 70: "Snow and ice", 80: "Water", 90: "Wetland", 95: "Mangroves", 100: "Moss and lichen" };
      const labels = stats.map((s) => classLabels[s.classId] || String(s.classId));
      const areaValues = stats.map((s) => (s.area_km2 != null ? Number(s.area_km2) : 0));
      if (barBox) barBox.style.flex = "1 1 550px";
      if (barCanvas) { barCanvas.style.width = "100%"; barCanvas.style.display = "block"; let containerH = polarCanvas && polarCanvas.clientHeight ? Math.round(polarCanvas.clientHeight) : barCanvas && barCanvas.clientHeight ? Math.round(barCanvas.clientHeight) : 220; barCanvas.style.height = Math.max(1, Math.round(containerH)) + "px"; }
      const colors = stats.map((s) => (classColorMap && classColorMap[s.classId]) || "#888888");
      if (statCanvas) renderChart(statCanvas, { type: "stat", value: `${totalAreaKm2.toFixed(2).toLocaleString('en-US')} km²`, label: "Total area (km²)", color: "#0E21A0", statFontSize: 28, statLabelFontSize: 12 });

      const chartPayload = { barCanvas, polarCanvas, labels, areaValues, colors };
      try { if (drawAreaEl) drawAreaEl.style.display = "none"; if (collapseDashboard) collapseDashboard(); if (expandDashboard) expandDashboard(); } catch (e) {}

      setTimeout(() => {
        try {
          const barBoxRect = barBox && barBox.getBoundingClientRect ? barBox.getBoundingClientRect() : { width: 300, height: 220 };
          const polarBoxRect = polarBox && polarBox.getBoundingClientRect ? polarBox.getBoundingClientRect() : { width: 300, height: 220 };
          const dpr = window.devicePixelRatio || 1;
          if (barCanvas) { barCanvas.width = Math.round(barBoxRect.width * dpr); barCanvas.height = Math.round(barBoxRect.height * dpr); barCanvas.style.width = barBoxRect.width + "px"; barCanvas.style.height = barBoxRect.height + "px"; }
          if (polarCanvas) { polarCanvas.width = Math.round(polarBoxRect.width * dpr); polarCanvas.height = Math.round(polarBoxRect.height * dpr); polarCanvas.style.width = polarBoxRect.width + "px"; polarCanvas.style.height = polarBoxRect.height + "px"; }

          const barChart = renderChart(chartPayload.barCanvas, { type: "bar", data: { labels: chartPayload.labels, values: chartPayload.areaValues }, backgroundColor: chartPayload.colors, label: "Land Cover Classification", showAllTicks: true, sort: false, barWidth: 35, horizontal: false, labelAngle: 0, animation: { duration: 300 }, options: { responsive: true, maintainAspectRatio: false } });

          try {
            chartPayload.barCanvas.addEventListener("click", (evt) => {
              try {
                const chart = (Chart && Chart.getChart && Chart.getChart(chartPayload.barCanvas)) || barChart;
                if (!chart) return;
                const elems = chart.getElementsAtEventForMode(evt, "nearest", { intersect: false }, false);
                if (!elems || elems.length === 0) return;
                const idx = elems[0].index;
                const chosen = chartPayload.colors && chartPayload.colors[idx] ? chartPayload.colors[idx] : null;
                if (chosen && setResponseColorFilter) setResponseColorFilter(chosen);
                chosen=null
              } catch (e) {}
            });
          } catch (e) {}
          const polarChart = renderChart(chartPayload.polarCanvas, { type: "doughnut", data: { labels: chartPayload.labels, values: chartPayload.areaValues }, backgroundColor: chartPayload.colors, label: "Area distribution (km²)", animation: { duration: 300 }, sort: false, borderWidth: 0, borderColor: "transparent", options: { responsive: true, maintainAspectRatio: false, cutout: "55%" } });

          try {
            chartPayload.polarCanvas.addEventListener("click", (evt) => {
              try {
                const chart = (Chart && Chart.getChart && Chart.getChart(chartPayload.polarCanvas)) || polarChart;
                if (!chart) return;
                const elems = chart.getElementsAtEventForMode(evt, "nearest", { intersect: true }, false);
                if (!elems || elems.length === 0) return;
                const idx = elems[0].index;
                const chosen = chartPayload.colors && chartPayload.colors[idx] ? chartPayload.colors[idx] : null;
                if (chosen && setResponseColorFilter) setResponseColorFilter(chosen);
                chosen = null;
              } catch (e) {}
            });
          } catch (e) {}
        } catch (err) { console.warn("Deferred chart rendering failed:", err); }
      }, 240);
    } catch (e) { console.warn("Updating histogram dashboard failed:", e); }

    return {
      warped,
      imgLayer: createResult.imgLayer,
      cut: createResult.cut,
      gwOpts,
      res,
    };
  } catch (e) {
    console.error("processShapes failed:", e);
    return null;
  }
}

