import Draw from "ol/interaction/Draw";
import VectorSource from "ol/source/Vector";
import { Vector as VectorLayer } from "ol/layer";
import Style from "ol/style/Style";
import Stroke from "ol/style/Stroke";
import Fill from "ol/style/Fill";
import { SpatialAnalysis } from "../spatial/analysis.js";
import { getArea } from "ol/sphere";
import Feature from "ol/Feature";
import GeoJSON from "ol/format/GeoJSON";

// Helper to manage a processing cursor on the map viewport. Uses a counter
// so nested operations don't prematurely clear the cursor.
function _incProcessingCursor(map) {
  try {
    const el = (map && typeof map.getViewport === "function") ? map.getViewport() : document.body;
    const cur = parseInt(el.getAttribute("data-processing-cnt") || "0", 10) || 0;
    el.setAttribute("data-processing-cnt", String(cur + 1));
    el.style.cursor = "wait";
  } catch (e) {
    // ignore
  }
}

function _decProcessingCursor(map) {
  try {
    const el = (map && typeof map.getViewport === "function") ? map.getViewport() : document.body;
    const cur = Math.max(0, (parseInt(el.getAttribute("data-processing-cnt") || "0", 10) || 0) - 1);
    el.setAttribute("data-processing-cnt", String(cur));
    if (cur === 0) {
      // If a tool has requested a specific cursor (e.g. selection pointer), restore it;
      // otherwise clear the cursor.
      const toolCursor = el.getAttribute("data-tool-cursor") || "";
      el.style.cursor = toolCursor;
    }
  } catch (e) {
    // ignore
  }
}

// Manage a persistent cursor requested by an active tool without interfering
// with the processing (wait) cursor. The processing cursor wins while active,
// and when processing completes the stored tool cursor is restored.
function _setToolCursor(map, cursor) {
  try {
    const el = (map && typeof map.getViewport === "function") ? map.getViewport() : document.body;
    if (cursor) {
      el.setAttribute("data-tool-cursor", cursor);
      const procCount = parseInt(el.getAttribute("data-processing-cnt") || "0", 10) || 0;
      if (procCount === 0) el.style.cursor = cursor;
    } else {
      el.removeAttribute("data-tool-cursor");
      const procCount = parseInt(el.getAttribute("data-processing-cnt") || "0", 10) || 0;
      if (procCount === 0) el.style.cursor = "";
    }
  } catch (e) {
    // ignore
  }
}

export class DrawingTool {
  constructor(map) {
    this.map = map;
    this.isActive = false;
    this.drawnShapes = [];
    this.drawingLayer = null;
    this.drawInteraction = null;
    this._onDrawCallbacks = [];
    this._onSketchCallbacks = [];
    this._onSelectCallbacks = [];
    this._searchCollection = null;
    this._clickHandler = null;
    this._sketchListener = null;

    this.initDrawingLayer();
  }

  initDrawingLayer() {
    // Create a layer to show drawn shapes
    const source = new VectorSource();
    const style = new Style({
      stroke: new Stroke({
        color: "#0e21a0",
        width: 2,
      }),
      fill: new Fill({
        color: "rgba(14, 33, 160, 0)",
      }),
    });

    this.drawingLayer = new VectorLayer({
      source: source,
      style: style,
    });
    this.map.addLayer(this.drawingLayer);
  }

  toggle(active) {
    this.isActive = active;

    if (active) {
      this.activateDrawing();
    } else {
      this.deactivateDrawing();
    }
  }

  activateDrawing() {
    if (this.drawInteraction) {
      this.map.removeInteraction(this.drawInteraction);
    }

    this.drawInteraction = new Draw({
      source: this.drawingLayer.getSource(),
      type: "Polygon",
      freehand: false,
    });

    this.drawInteraction.on("drawstart", (evt) => {
      try {
        // Clear any existing drawn shapes when starting a new sketch
        try {
          this.clearShapes();
        } catch (e) {}
        // Also request the map to clear any response imagery if the host app provides it
        try {
          if (this.map && typeof this.map.clearResponses === "function") this.map.clearResponses();
        } catch (e) {}

        const sketch = evt.feature;
        const geom = sketch.getGeometry();
        // attach a change listener to provide live updates
        this._sketchListener = geom.on("change", (e) => {
          try {
            const area = getArea(e.target);
            // notify sketch listeners with current area (sq meters) and the sketch feature
            this._onSketchCallbacks.forEach((cb) => {
              try {
                cb({ area, feature: sketch });
              } catch (er) {
                console.warn("sketch cb error", er);
              }
            });
          } catch (err) {
            console.warn("sketch change handler failed", err);
          }
        });
      } catch (err) {
        console.warn("drawstart handler failed", err);
      }
    });

    this.drawInteraction.on("drawend", async (event) => {
      const feature = event.feature;
      // remove sketch listener if present
      try {
        if (this._sketchListener) {
          this._sketchListener.unlisten();
        }
      } catch (e) {}
      this.drawnShapes.push(feature);
      console.log(`Shape drawn. Total shapes: ${this.drawnShapes.length}`);
      // notify listeners with a shallow copy of shapes. If callbacks return Promises
      // we await them so the UI can indicate processing until all complete.
      try {
        _incProcessingCursor(this.map);
        const results = this._onDrawCallbacks.map((cb) => {
          try {
            return cb(this.drawnShapes.slice());
          } catch (e) {
            console.warn("draw callback error:", e);
            return Promise.resolve();
          }
        });
        await Promise.allSettled(results);
      } catch (e) {
        console.warn("error while invoking draw callbacks", e);
      } finally {
        _decProcessingCursor(this.map);
      }
    });

    this.map.addInteraction(this.drawInteraction);
  }

  deactivateDrawing() {
    if (this.drawInteraction) {
      this.map.removeInteraction(this.drawInteraction);
      this.drawInteraction = null;
    }
  }

  getDrawnShapes() {
    return this.drawnShapes;
  }

  clearShapes() {
    this.drawingLayer.getSource().clear();
    this.drawnShapes = [];
    // notify listeners that shapes were cleared
    try {
      this._onDrawCallbacks.forEach((cb) => {
        try {
          cb(this.drawnShapes.slice());
        } catch (e) {
          console.warn("draw callback error:", e);
        }
      });
    } catch (e) {
      // ignore
    }
  }

  /**
   * Public deactivate for external callers to turn off the tool
   */
  deactivate() {
    try {
      this.toggle(false);
      this.isActive = false;
    } catch (e) {
      // ignore
    }
  }

  /**
   * Register a callback invoked when a new shape is drawn or shapes cleared.
   * Callback receives an array of drawn features (may be empty).
   */
  onDraw(cb) {
    if (typeof cb === "function") this._onDrawCallbacks.push(cb);
  }

  /**
   * Register a callback invoked while sketch is being drawn.
   * Callback receives an object: { area: <sqm>, feature: <OL Feature> }
   */
  onSketch(cb) {
    if (typeof cb === "function") this._onSketchCallbacks.push(cb);
  }

  onSelect(cb) {
    if (typeof cb === "function") this._onSelectCallbacks.push(cb);
  }

  setSearchCollection(collection) {
    this._searchCollection = collection;
  }

  enablePointSelection(enable = true) {
    if (enable) {
      if (this._clickHandler) return;
      this._clickHandler = async (evt) => {
        try {
          const coord = evt.coordinate;
          const hits = SpatialAnalysis.findFeaturesContainingPoint(
            this._searchCollection || { features: [] },
            coord,
          );
          try {
            _incProcessingCursor(this.map);
            const results = this._onSelectCallbacks.map((cb) => {
              try {
                return cb(hits);
              } catch (e) {
                console.warn("onSelect cb error", e);
                return Promise.resolve();
              }
            });
            await Promise.allSettled(results);
          } catch (e) {
            console.warn("error while invoking onSelect callbacks", e);
          } finally {
            _decProcessingCursor(this.map);
          }
        } catch (e) {
          console.warn("point selection handler failed", e);
        }
      };
      this.map.on("singleclick", this._clickHandler);
    } else {
      if (this._clickHandler) {
        this.map.un("singleclick", this._clickHandler);
        this._clickHandler = null;
      }
    }
  }
}

export class SelectionTool {
  constructor(map) {
    this.map = map;
    this.isActive = false;
    this._searchCollection = null;
    this._onSelectCallbacks = [];
    this._clickHandler = null;
    this._hoverHandler = null;
    this._hoveredFeature = null;
    this._hoveredLayer = null;
    this._selectedLayer = null;
    this._tooltip = null;
    this.initSelectionLayers();
  }

  initSelectionLayers() {
    // Selection layer (persistent, orange/blue fill)
    const selectSource = new VectorSource();
    const selectStyle = new Style({
      stroke: new Stroke({ color: "#0e21a0", width: 2 }),
      fill: new Fill({ color: "rgba(14, 33, 160, 0)" }),
    });
    this._selectedLayer = new VectorLayer({
      source: selectSource,
      style: selectStyle,
    });
    this.map.addLayer(this._selectedLayer);

    // Hover layer (temporary, yellow highlight)
    const hoverSource = new VectorSource();
    const hoverStyle = new Style({
      stroke: new Stroke({ color: "#79a8ff", width: 3 }),
      fill: new Fill({ color: "rgba(203, 128, 6, 0.55)" }),
    });
    this._hoveredLayer = new VectorLayer({
      source: hoverSource,
      style: hoverStyle,
    });
    this.map.addLayer(this._hoveredLayer);
  }

  toggle(active) {
    this.isActive = active;
    if (active) {
      this.activate();
    } else {
      this.deactivate();
    }
  }

  activate() {
    if (this._clickHandler) return;

    // indicate selection mode with a pointer cursor
    _setToolCursor(this.map, "pointer");

    this._clickHandler = async (evt) => {
      if (!this.isActive) return;
      try {
        const coord = evt.coordinate;
        const hits = SpatialAnalysis.findFeaturesContainingPoint(
          this._searchCollection || { features: [] },
          coord,
        );
        if (hits && hits.length > 0) {
          const feature = hits[0];
          // Store WGS84 feature directly in a data property on OL feature for later retrieval
          const geojsonFormat = new GeoJSON();
          const olFeature = geojsonFormat.readFeature(feature, {
            dataProjection: "EPSG:4326",
            featureProjection: "EPSG:3857",
          });
          // Attach the original WGS84 feature
          olFeature.set("_wgs84Feature", feature, true);
          // Clear previous selection before adding this one so second selection replaces earlier ones
          try {
            this._selectedLayer.getSource().clear();
          } catch (e) {}
          this._selectedLayer.getSource().addFeature(olFeature);
          // Also request the map to clear any response imagery if the host app provides it
          try {
            if (this.map && typeof this.map.clearResponses === "function") this.map.clearResponses();
          } catch (e) {}

          // Notify callbacks with ALL currently selected features (as WGS84 GeoJSON Feature objects)
          const allSelected = this._selectedLayer
            .getSource()
            .getFeatures()
            .map((olF) => {
              // Return the stored WGS84 feature directly instead of round-tripping through writeFeature
              const storedFeature = olF.get("_wgs84Feature");
              if (storedFeature) {
                return storedFeature;
              }
              // Fallback for non-WGS84-stored features
              const geojsonFmt = new GeoJSON();
              const jsonStr = geojsonFmt.writeFeature(olF, {
                dataProjection: "EPSG:3857",
                featureProjection: "EPSG:4326",
              });
              return JSON.parse(jsonStr);
            });
          try {
            _incProcessingCursor(this.map);
            const results = this._onSelectCallbacks.map((cb) => {
              try {
                return cb(allSelected);
              } catch (e) {
                console.warn("onSelect cb error", e);
                return Promise.resolve();
              }
            });
            await Promise.allSettled(results);
          } catch (e) {
            console.warn("error while invoking onSelect callbacks", e);
          } finally {
            _decProcessingCursor(this.map);
          }
        }
      } catch (e) {
        console.warn("selection click handler failed", e);
      }
    };

    this._hoverHandler = (evt) => {
      if (!this.isActive) return;
      try {
        const coord = evt.coordinate;
        const hits = SpatialAnalysis.findFeaturesContainingPoint(
          this._searchCollection || { features: [] },
          coord,
        );

        // Clear hover layer before adding new hover
        const hoverSource = this._hoveredLayer.getSource();
        hoverSource.clear();
        this._hoveredFeature = null;

        if (hits && hits.length > 0) {
          const geojsonFormat = new GeoJSON();
          const olFeature = geojsonFormat.readFeature(hits[0], {
            dataProjection: "EPSG:4326",
            featureProjection: "EPSG:3857",
          });
          this._hoveredFeature = olFeature;
          // Add to hover layer
          hoverSource.addFeature(olFeature);

          // Show tooltip
          const name = hits[0].properties?.name || "";
          if (name) {
            if (!this._tooltip) {
              this._tooltip = document.createElement("div");
              this._tooltip.id = "gov-hover-tooltip";
              this._tooltip.style.position = "fixed";
              this._tooltip.style.pointerEvents = "none";
              this._tooltip.style.padding = "4px 8px";
              this._tooltip.style.background = "rgba(0,0,0,0.8)";
              this._tooltip.style.color = "white";
              this._tooltip.style.borderRadius = "3px";
              this._tooltip.style.fontSize = "12px";
              this._tooltip.style.zIndex = "10000";
              document.body.appendChild(this._tooltip);
            }
            this._tooltip.style.display = "block";
            this._tooltip.textContent = name;
            const clientX = evt.originalEvent?.clientX || evt.pixel[0] || 0;
            const clientY = evt.originalEvent?.clientY || evt.pixel[1] || 0;
            this._tooltip.style.left = clientX + 12 + "px";
            this._tooltip.style.top = clientY + 12 + "px";
          }
        } else {
          if (this._tooltip) {
            this._tooltip.style.display = "none";
          }
        }
      } catch (e) {
        console.warn("hover handler failed", e);
      }
    };

    this.map.on("singleclick", this._clickHandler);
    this.map.on("pointermove", this._hoverHandler);
  }

  deactivate() {
    this.isActive = false;
    // clear any tool-requested cursor
    _setToolCursor(this.map, "");
    if (this._clickHandler) {
      this.map.un("singleclick", this._clickHandler);
      this._clickHandler = null;
    }
    if (this._hoverHandler) {
      this.map.un("pointermove", this._hoverHandler);
      this._hoverHandler = null;
    }
    if (this._hoveredLayer) {
      this._hoveredLayer.getSource().clear();
    }
    this._hoveredFeature = null;
    if (this._tooltip) {
      this._tooltip.style.display = "none";
    }
  }

  clearSelection() {
    if (this._selectedLayer) {
      this._selectedLayer.getSource().clear();
    }
  }

  setSearchCollection(collection) {
    this._searchCollection = collection;
  }

  onSelect(cb) {
    if (typeof cb === "function") this._onSelectCallbacks.push(cb);
  }

  getSelectedFeatures() {
    return this._selectedLayer
      .getSource()
      .getFeatures()
      .map((olF) => {
        // Return the stored WGS84 feature directly
        const storedFeature = olF.get("_wgs84Feature");
        if (storedFeature) {
          return storedFeature;
        }
        // Fallback for features added without stored WGS84
        const geojsonFormat = new GeoJSON();
        const jsonStr = geojsonFormat.writeFeature(olF, {
          dataProjection: "EPSG:3857",
          featureProjection: "EPSG:4326",
        });
        return JSON.parse(jsonStr);
      });
  }
}
