import "./new-panel.css";
/**
 * Creates a modern, animated "Peek" panel.
 * @returns {HTMLElement} The panel element.
 */
export function createSlidingPanel() {
    // 1. Create the styles


    // 2. Create the HTML Structure
    const panel = document.createElement('div');
    panel.className = 'js-sliding-panel';
    
    panel.innerHTML = `
        <div class="js-panel-header">
            <svg class="js-panel-arrow" viewBox="0 0 24 24">
                <path d="M18 15l-6-6-6 6" stroke-linecap="round" stroke-linejoin="round"/>
            </svg>
        </div>
        <div class="js-panel-content">
           
        </div>
    `;

    // 3. Logic
    const toggle = () => panel.classList.toggle('is-open');

    // Click header/tab to open
    panel.querySelector('.js-panel-header').addEventListener('click', toggle);
   
    // Close button logic


    return  panel;
}

