import Map from "ol/Map";
import View from "ol/View";
import { fromLonLat } from "ol/proj";
import { defaults as defaultControls } from "ol/control";

function ensureMapInitCssLoaded() {
  if (typeof document === "undefined") return;
  if (document.getElementById("map-init-css")) return;
  try {
    const href = new URL("../ui/map-init.css", import.meta.url).href;
    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.id = "map-init-css";
    link.href = href;
    document.head.appendChild(link);
  } catch (e) {
    // Fallback: do nothing if URL resolution isn't allowed in this environment
  }
}

/**
 * Initialize an OpenLayers Map.
 * Accepts either:
 * - an HTMLElement (legacy calls), or
 * - an options object: { target, center = [lon,lat], zoom }
 */
export function initMap(opts) {
  // Normalize parameters
  let target = null;
  let center = [27, 30]; // default to Egypt center
  let zoom = 2;

  if (!opts) {
    throw new Error("initMap requires a target element or options object");
  }

  if (opts instanceof HTMLElement || typeof opts === "string") {
    target = opts;
  } else if (typeof opts === "object") {
    target = opts.target;
    center = opts.center || center;
    zoom = typeof opts.zoom === "number" ? opts.zoom : zoom;
  } else {
    throw new Error("Unsupported initMap arguments");
  }

  // Controls option: default to true (show OL default controls)
  let useDefaultControls = false;
  if (typeof opts === "object" && typeof opts.controls !== "undefined") {
    // allow callers to pass { controls: false } to hide the default controls
    useDefaultControls = Boolean(opts.controls);
  }

  // Resolve string id to element when needed
  let targetEl = null;
  if (typeof target === "string") {
    targetEl = document.getElementById(target);
  } else if (target instanceof HTMLElement) {
    targetEl = target;
  }

  // Load the map-init CSS and add the initialization class to the element
  ensureMapInitCssLoaded();
  try {
    if (targetEl) {
      targetEl.classList.add("map-initialized");
    }
  } catch (e) {
    // ignore if DOM ops fail in non-browser environments
  }

  // Build view options and allow callers to pass minZoom/extent/constrainOnlyCenter
  const viewOpts = {
    center: fromLonLat(center),
    zoom: zoom,
  };
  if (typeof opts.minZoom === "number") viewOpts.minZoom = opts.minZoom;
  if (opts.extent) viewOpts.extent = opts.extent;
  if (typeof opts.constrainOnlyCenter !== "undefined") viewOpts.constrainOnlyCenter = Boolean(opts.constrainOnlyCenter);

  const map = new Map({
    target: target, // OL accepts either element or id
    layers: [],
    view: new View(viewOpts),
    // Use defaultControls() to get Zoom buttons, or [] for no controls
    controls: useDefaultControls ? defaultControls() : [],
  });

  // Initialize the dynamic registry on the map object
  map.set("baseMapRegistry", {});

  return map;
}

/**
 * Manually adds a layer to the base map system
 */
export function registerBaseMap(map, id, layer, isVisible = false) {
  const registry = map.get("baseMapRegistry");

  // Set properties so we know it's a base layer
  layer.set("id", id);
  layer.setVisible(isVisible);

  // Store in registry
  registry[id] = layer;

  // Always insert base maps at the bottom (index 0)
  map.getLayers().insertAt(0, layer);

  // Trigger a custom event so the UI knows to refresh its buttons
  map.dispatchEvent({ type: "basemap-added", id: id });
}

export function switchBaseMap(map, key) {
  const registry = map.get("baseMapRegistry");
  Object.keys(registry).forEach((id) => {
    registry[id].setVisible(id === key);
  });
}
