import { createSlidingPanel } from "./new-panel";

// Create dashboard chart canvases, wrappers and a sliding panel container.
export function initDashboardUI({ dashboard } = {}) {
  const statCanvas = document.createElement("canvas");
  statCanvas.classList.add("created-stat-canvas");

  const barCanvas = document.createElement("canvas");
  barCanvas.classList.add("created-bar-canvas");
  const polarCanvas = document.createElement("canvas");
  polarCanvas.classList.add("created-polar-canvas");

  const barBox = document.createElement("div");
  barBox.className = "hist-chart-box hist-chart-box--bar";
  barBox.appendChild(barCanvas);

  const polarBox = document.createElement("div");
  polarBox.className = "hist-chart-box hist-chart-box--polar";
  polarBox.appendChild(polarCanvas);
  polarBox.style.minWidth = "280px";
  const statBox = document.createElement("div");
  statBox.className = "hist-chart-box hist-chart-box--stat";
  statBox.appendChild(statCanvas);

  const slidingPanel = createSlidingPanel();
  document.body.appendChild(slidingPanel);
  const panelContent = slidingPanel.querySelector(".js-panel-content");
  if (panelContent) {
    panelContent.appendChild(barBox);
    panelContent.appendChild(polarBox);
    panelContent.appendChild(statBox);
  }

  // If a Dashboard instance was provided, optionally mount sections there
  return { statCanvas, barCanvas, polarCanvas, barBox, polarBox, statBox, slidingPanel };
}

export function collapseDashboard(dashboard, slidingPanel) {

  try {
    if (slidingPanel && slidingPanel.classList) slidingPanel.classList.remove("is-open");
  } catch (e) {}
}

export function expandDashboard(dashboard, slidingPanel) {

  try {
    if (slidingPanel && slidingPanel.classList) slidingPanel.classList.add("is-open");
  } catch (e) {}
}

export function clearDashboardCharts({ statCanvas, barCanvas, polarCanvas, Chart }) {
  [statCanvas, barCanvas, polarCanvas].forEach((c) => {
    if (!c) return;
    try {
      const existingChart = Chart && Chart.getChart ? Chart.getChart(c) : null;
      if (existingChart && typeof existingChart.destroy === "function") {
        try { existingChart.destroy(); } catch (ee) {}
      }
      if (c._chartResizeObserver && typeof c._chartResizeObserver.disconnect === "function") {
        try { c._chartResizeObserver.disconnect(); } catch (ee) {}
        try { delete c._chartResizeObserver; } catch (ee) {}
      }
      const ctx = c.getContext && c.getContext("2d");
      if (ctx) ctx.clearRect(0, 0, c.width || 0, c.height || 0);
    } catch (err) {}
    try {
      c.style.width = c.style.width || "";
      c.style.height = c.style.height || "";
      try { c.width = 0; c.height = 0; } catch (ee) {}
    } catch (err) {}
  });
}

// Render charts into provided canvases and wire click callbacks to setResponseColorFilter.
// `renderChart` is the project's chart helper; `Chart` is Chart.js (optional) for cleanup.
export function renderAndWireCharts({ barCanvas, polarCanvas, statCanvas, barBox, polarBox }, { labels, values, colors }, { renderChart, Chart, setResponseColorFilter, collapseDashboard, expandDashboard, drawAreaEl } = {}) {
  try {
    if (barBox) barBox.style.flex = "0 0 50%";
    if (barCanvas) {
      barCanvas.style.width = "100%";
      barCanvas.style.display = "block";
      let containerH = (polarCanvas && polarCanvas.clientHeight) ? Math.round(polarCanvas.clientHeight) : (barCanvas && barCanvas.clientHeight ? Math.round(barCanvas.clientHeight) : 220);
      barCanvas.style.height = Math.max(1, Math.round(containerH)) + "px";
    }

    if (statCanvas && renderChart) {
      // total stat rendered by caller (stat value expected in values.reduce)
      // The caller should render stat separately if desired; keep compatibility
    }

    const chartPayload = { barCanvas, polarCanvas, labels, areaValues: values, colors };

    // Defer rendering slightly to allow layout to settle
    setTimeout(() => {
      try {
        const barBoxRect = barBox && barBox.getBoundingClientRect ? barBox.getBoundingClientRect() : { width: 300, height: 220 };
        const polarBoxRect = polarBox && polarBox.getBoundingClientRect ? polarBox.getBoundingClientRect() : { width: 300, height: 220 };
        const dpr = window.devicePixelRatio || 1;
        if (barCanvas) { barCanvas.width = Math.round(barBoxRect.width * dpr); barCanvas.height = Math.round(barBoxRect.height * dpr); barCanvas.style.width = barBoxRect.width + "px"; barCanvas.style.height = barBoxRect.height + "px"; }
        if (polarCanvas) { polarCanvas.width = Math.round(polarBoxRect.width * dpr); polarCanvas.height = Math.round(polarBoxRect.height * dpr); polarCanvas.style.width = polarBoxRect.width + "px"; polarCanvas.style.height = polarBoxRect.height + "px"; }

        const barChart = renderChart(chartPayload.barCanvas, { type: "bar", data: { labels: chartPayload.labels, values: chartPayload.areaValues }, backgroundColor: chartPayload.colors, label: "Land Cover Classification", showAllTicks: true, sort: false, barWidth: 35, horizontal: false, labelAngle: 0, animation: { duration: 300 }, options: { responsive: true, maintainAspectRatio: false } });

        try {
          chartPayload.barCanvas.addEventListener("click", (evt) => {
            try {
              const chart = (Chart && Chart.getChart && Chart.getChart(chartPayload.barCanvas)) || barChart;
              if (!chart) return;
              const elems = chart.getElementsAtEventForMode(evt, "nearest", { intersect: false }, false);
              if (!elems || elems.length === 0) return;
              const idx = elems[0].index;
              const chosen = chartPayload.colors && chartPayload.colors[idx] ? chartPayload.colors[idx] : null;
              if (chosen && setResponseColorFilter) setResponseColorFilter(chosen);
            } catch (e) {}
          });
        } catch (e) {}

        const polarChart = renderChart(chartPayload.polarCanvas, { type: "doughnut", data: { labels: chartPayload.labels, values: chartPayload.areaValues }, backgroundColor: chartPayload.colors, label: "Area distribution (km²)", animation: { duration: 300 }, sort: false, borderWidth: 0, borderColor: "transparent", options: { responsive: true, maintainAspectRatio: false, cutout: "55%" } });

        try {
          chartPayload.polarCanvas.addEventListener("click", (evt) => {
            try {
              const chart = (Chart && Chart.getChart && Chart.getChart(chartPayload.polarCanvas)) || polarChart;
              if (!chart) return;
              const elems = chart.getElementsAtEventForMode(evt, "nearest", { intersect: false }, false);
              if (!elems || elems.length === 0) return;
              const idx = elems[0].index;
              const chosen = chartPayload.colors && chartPayload.colors[idx] ? chartPayload.colors[idx] : null;
              if (chosen && setResponseColorFilter) setResponseColorFilter(chosen);
            } catch (e) {}
          });
        } catch (e) {}
      } catch (err) { console.warn("Deferred chart rendering failed:", err); }
    }, 240);

    return true;
  } catch (e) {
    console.warn("renderAndWireCharts failed:", e);
    return false;
  }
}
