import * as GeoTIFF from "geotiff";
import proj4 from "proj4";

// Helper: create an image from band arrays and trigger a download
export function downloadWarpImage(
  bandArrays,
  width,
  height,
  filename = "warp-result.png",
) {
  try {
    const bands = Array.isArray(bandArrays) ? bandArrays : [bandArrays];
    const bandCount = bands.length || 1;
    const getBand = (i) => bands[Math.min(i, bandCount - 1)];

    const pixelCount = width * height;
    const out = new Uint8ClampedArray(pixelCount * 4);

    for (let i = 0; i < pixelCount; i++) {
      const r = Math.round(Math.max(0, Math.min(255, getBand(0)[i] || 0)));
      const g = Math.round(Math.max(0, Math.min(255, getBand(1)[i] || r)));
      const b = Math.round(Math.max(0, Math.min(255, getBand(2)[i] || r)));
      const idx = i * 4;
      out[idx] = r;
      out[idx + 1] = g;
      out[idx + 2] = b;
      out[idx + 3] = 255;
    }

    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext("2d");
    const img = new ImageData(out, width, height);
    ctx.putImageData(img, 0, 0);

    canvas.toBlob((blob) => {
      if (!blob) return;
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
    }, "image/png");
  } catch (e) {
    console.warn("downloadWarpImage failed:", e);
  }
}

/**
 * Reads a specific extent, automatically choosing the best resolution level
 * to keep the output image size below 'maxSize' pixels.
 * @param {string} url - URL of the GeoTIFF
 * @param {Array<number>} extent4326 - [minLon, minLat, maxLon, maxLat]
 * @param {number} maxSize - Target width/height in pixels (e.g., 500 or 1000)
 */
export async function readTiffAutoLevel(url, extent4326, maxSize = 2000) {
  const tiff = await GeoTIFF.fromUrl(url);

  // 1. Load Level 0 Metadata (The Reference)
  const image0 = await tiff.getImage(0);
  const width0 = image0.getWidth();
  const origin = image0.getOrigin();
  const resolution0 = image0.getResolution();
  const geoKeys = image0.getGeoKeys();

  // 2. Setup Projection (Using the same logic as before)
  const epsgCode =
    geoKeys.ProjectedCSTypeGeoKey || geoKeys.GeographicTypeGeoKey;
  let tiffProjString;

  if (epsgCode === 3857) {
    tiffProjString =
      "+proj=merc +a=6378137 +b=6378137 +lat_ts=0.0 +lon_0=0.0 +x_0=0.0 +y_0=0 +k=1.0 +units=m +nadgrids=@null +wktext +no_defs";
  } else if (epsgCode === 32636) {
    tiffProjString = "+proj=utm +zone=36 +datum=WGS84 +units=m +no_defs";
  } else if (epsgCode === 4326) {
    tiffProjString = "+proj=longlat +datum=WGS84 +no_defs";
  } else {
    tiffProjString = "+proj=utm +zone=35 +datum=WGS84 +units=m +no_defs";
  }

  // 3. Project the Extent
  const minPt = proj4("EPSG:4326", tiffProjString, [
    extent4326[0],
    extent4326[1],
  ]);
  const maxPt = proj4("EPSG:4326", tiffProjString, [
    extent4326[2],
    extent4326[3],
  ]);

  // 4. Calculate "Virtual" Width at Level 0
  const virtualWidth = Math.abs((maxPt[0] - minPt[0]) / resolution0[0]);
  const virtualHeight = Math.abs((maxPt[1] - minPt[1]) / resolution0[1]);

  // 5. Determine the Best Level
  const areaRatio = (virtualWidth * virtualHeight) / (maxSize * maxSize);
  let level = 0;
  if (areaRatio > 1) {
    level = Math.ceil(Math.log2(areaRatio) / 2);
  }

  // Safety: Ensure we don't request a level that doesn't exist
  const maxLevels = await tiff.getImageCount();
  if (level >= maxLevels) {
    level = maxLevels - 1;
  }

  console.log(
    `Auto-Level Decision: Requested ~${Math.round(virtualWidth)}px width. Constraint ${maxSize}px. -> Using Level ${level}`,
  );

  // 6. Load the Target Level
  const imageTarget = await tiff.getImage(level);
  const widthTarget = imageTarget.getWidth();

  // Calculate inherited resolution (Metadata Fix)
  const scaleFactor = width0 / widthTarget;
  const resolutionTarget = [
    resolution0[0] * scaleFactor,
    resolution0[1] * scaleFactor,
  ];

  // 7. Calculate Window
  const x1 = (minPt[0] - origin[0]) / resolutionTarget[0];
  const y1 = (minPt[1] - origin[1]) / resolutionTarget[1];
  const x2 = (maxPt[0] - origin[0]) / resolutionTarget[0];
  const y2 = (maxPt[1] - origin[1]) / resolutionTarget[1];

  const window = [
    Math.round(Math.min(x1, x2)),
    Math.round(Math.min(y1, y2)),
    Math.round(Math.max(x1, x2)),
    Math.round(Math.max(y1, y2)),
  ];

  const actualRasterBBox = [
    origin[0] + window[0] * resolutionTarget[0], // minX
    origin[1] + window[3] * resolutionTarget[1], // minY
    origin[0] + window[2] * resolutionTarget[0], // maxX
    origin[1] + window[1] * resolutionTarget[1], // maxY
  ];

  // 8. Read Data
  const pool = new GeoTIFF.Pool();
  const data = await imageTarget.readRasters({ window: window, pool: pool });

  return {
    width: data.width,
    height: data.height,
    data: data[0],
    levelUsed: level,
    actualRasterBBox: actualRasterBBox,
  };
}
