export class LayerSwitcher {
  constructor(map, options = {}) {
    this.map = map;
    this.layers = [];
    this.element = this.render();
    
    if (this.map) {
      const onMethod = this.map.on ? "on" : "addEventListener";
      this.map[onMethod]("basemap-added", () => this.update());
    }
  }

  update() {
    const list = this.element.querySelector(".layer-list");
    if (!list) return;
    list.innerHTML = "";

    // 1. Render Basemaps (Non-draggable)
    if (this.map) {
      const registry = this.map.get("baseMapRegistry") || {};
      Object.keys(registry).forEach((id) => {
        const layer = registry[id];
        list.appendChild(this.createLayerRow(id, layer, true));
      });
    }

    // 2. Render Overlay Layers (Draggable)
    this.layers.forEach(({ name, layer }) => {
      const row = this.createLayerRow(name, layer, false);
      
      row.setAttribute("draggable", "true");
      this.addDragListeners(row, name);
      
      list.appendChild(row);
    });
  }

  createLayerRow(name, layer, isBasemap) {
    const row = document.createElement("div");
    row.className = `layer-row ${isBasemap ? 'basemap-row' : ''}`;
    
    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.style.cursor = "pointer";
    checkbox.checked = layer.getVisible ? layer.getVisible() : true;
    
    checkbox.onchange = (e) => {
      if (layer.setVisible) layer.setVisible(e.target.checked);
      row.classList.toggle('active', e.target.checked);
    };

    if (checkbox.checked) row.classList.add('active');

    const label = document.createElement("span");
    label.className = "layer-label";
    label.innerText = name;

    row.appendChild(checkbox);
    row.appendChild(label);

    // Stop checkbox/label clicks from triggering drag accidentally
    row.onclick = (e) => {
        if(e.target !== checkbox) checkbox.click();
    };

    return row;
  }

  addDragListeners(row, name) {
    row.addEventListener("dragstart", (e) => {
      this.draggedName = name; // Store globally in class to avoid serialization issues
      row.classList.add("dragging");
      e.dataTransfer.effectAllowed = "move";
      
      // Fix for "selecting all" text issue:
      // Clear any text selection that happened right as drag started
      window.getSelection().removeAllRanges();
    });

    row.addEventListener("dragover", (e) => {
      e.preventDefault(); // Necessary to allow drop
      e.dataTransfer.dropEffect = "move";
      row.classList.add("drag-over");
    });

    row.addEventListener("dragleave", () => {
      row.classList.remove("drag-over");
    });

    row.addEventListener("drop", (e) => {
      e.preventDefault();
      row.classList.remove("drag-over");
      
      const targetName = name;
      if (this.draggedName && this.draggedName !== targetName) {
        this.reorderLayers(this.draggedName, targetName);
      }
    });

    row.addEventListener("dragend", () => {
      row.classList.remove("dragging");
      this.element.querySelectorAll(".layer-row").forEach(r => r.classList.remove("drag-over"));
      this.draggedName = null;
    });
  }

reorderLayers(draggedName, targetName) {
    const fromIdx = this.layers.findIndex(l => l.name === draggedName);
    const toIdx = this.layers.findIndex(l => l.name === targetName);
    
    // 1. Move the item in our internal array
    const [movedItem] = this.layers.splice(fromIdx, 1);
    this.layers.splice(toIdx, 0, movedItem);

    // 2. Sync with OpenLayers using Z-Index
    // We iterate through the array and assign Z-indices based on position.
    // Higher index in array = Higher Z-Index on map (Top).
    this.layers.forEach((layerObj, index) => {
      if (layerObj.layer && layerObj.layer.setZIndex) {
        // We add a base offset (e.g., 10) to stay above basemaps
        layerObj.layer.setZIndex(index + 10);
      }
    });

    // 3. Optional: If you prefer physical re-insertion over Z-index:
    /*
    if (this.map && this.map.getLayers) {
      const layerCollection = this.map.getLayers();
      this.layers.forEach(({ layer }) => {
        layerCollection.remove(layer);
        layerCollection.push(layer);
      });
    }
    */

    this.update();
  }
  render() {
    const container = document.createElement("div");
    container.className = "layer-switcher";
    container.innerHTML = `<div class="layer-list"></div>`;
    
    if (!document.getElementById('layer-switcher-styles')) {



      
      const style = document.createElement('style');
      style.id = 'layer-switcher-styles';

      style.textContent = `
        .layer-switcher {
          user-select: none;
          -webkit-user-select: none;
          font-family: 'Segoe UI', system-ui, sans-serif;
          width: 10px; /* Narrowed width */
        }
        .layer-list {
          display: flex;
          flex-direction: column;
          gap: 4px; /* Tighter gap between buttons */
        }
        .layer-row { 
          display: flex; 
          align-items: center; 
          padding: 6px 10px; /* Reduced padding */          
          border: 1px solid #ddd; 
          background: #ffffff; 
          cursor: grab; 
          border-radius: 4px; /* Sharper corners for a smaller look */
          transition: all 0.15s ease;
          color: #333333;
          font-size: 0.85rem; /* Smaller font */
        }
        .layer-row:active { cursor: grabbing; }
        
        /* HIDDEN CHECKBOX */
        .layer-row input[type="checkbox"] {
          display: none;
        }

        /* ACTIVE STATE */
        .layer-row.active { 
          background: #354085f4 !important; 
          border-color: #0b1a80;
        }

        /* WHITE TEXT */
        .layer-row.active, 
        .layer-row.active .layer-label { 
          color: #ffffff !important; 
        }

        .layer-row.dragging { 
          opacity: 0.3; 
          transform: scale(0.98);
        }

        .layer-row.drag-over { 
          border-top: 2px solid #007bff; 
          background: #f0f7ff; 
        }
        
        .layer-label { 
          flex-grow: 1; 
          font-weight: 500; 
          pointer-events: none; 
          text-align: left; /* Switched back to left for better readability at small sizes */
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis; /* Keeps long names from breaking the UI */
        }
        
        .basemap-row { 
          border-left: 3px solid #6c757d; 
          cursor: pointer; 
        }
      `;
      
      document.head.appendChild(style);
    }
    
    return container;
  }

  addLayer(name, controller) {
    if (!this.layers.some((l) => l.name === name)) {
      this.layers.push({ name, layer: controller });
      this.update();
    }
  }

  mount(target) {
    let parent = (typeof target === "string") ? document.querySelector(target) : target;
    if (!parent) {
        parent = document.createElement("div");
        parent.id = "gis-floating-dock";
        parent.style.position = "absolute";
        parent.style.top = "10px";
        parent.style.right = "10px";
        parent.style.zIndex = "1000";
        document.body.appendChild(parent);
    }
    parent.appendChild(this.element);
    this.update();
  }
}